"""Era I overworld tiles and character sprites (original, generated by this script).

Writes:
  art/era1/tiles/overworld.png   atlas: column = TilesetFactory.Kind, row = variant (16 x 16 px)
  art/era1/chars/<style>.png     64 x 32 sheet: columns down, up, left, right; rows stand, step

Variant rows: for PATH, WATER, ROOF, WALL, FENCE, CLIFF, PIER the row is a neighbour mask
(1 = same kind above, 2 = right, 4 = below, 8 = left). For GRASS, TALL_GRASS, TREE and
FLOWER it is a cosmetic variant 0..3 picked from the cell position.
Run: python3 tools/art/gen_tiles.py (from the repo root).
"""
from __future__ import annotations

import os
import random

from px import Canvas

T = 16
KINDS = ["GRASS", "TALL_GRASS", "PATH", "WATER", "TREE", "WALL", "ROOF", "DOOR", "FLOOR",
         "FENCE", "SIGN", "FLOWER", "COUNTER", "INNER_WALL", "SPRING", "RIFT",
         "CLIFF", "STAIRS", "REEDS", "SCREE", "PIER", "TOWER", "LAMP", "ROCK",
         "WADE", "BOULDER", "PLATE", "CRACKED", "VINES", "PLANK"]
K = {name: i for i, name in enumerate(KINDS)}
UP, RIGHT, DOWN, LEFT = 1, 2, 4, 8


def grass(c: Canvas, ox: int, oy: int, variant: int) -> None:
    c.rect(ox, oy, T, T, 2)
    rng = random.Random(100 + variant)
    # Small "v" tufts and light specks; a different scatter per variant.
    for _ in range(3):
        x, y = rng.randrange(1, 14), rng.randrange(2, 15)
        c.set(ox + x, oy + y, 1)
        c.set(ox + x + 2, oy + y, 1)
        c.set(ox + x + 1, oy + y + 1, 1)
    for _ in range(4):
        c.set(ox + rng.randrange(0, 16), oy + rng.randrange(0, 16), 3)


def tall_grass(c: Canvas, ox: int, oy: int, variant: int) -> None:
    grass(c, ox, oy, variant)
    # Two rows of leaf clumps: dark blade outlines with a lit tip, offset per row.
    clump = ["..0..0..",
             ".030.30.",
             "0320320.",
             "0221221.",
             "01110110",
             ".000.00."]
    for row, (dy, dx) in enumerate([(1, 0 + variant % 2), (9, 4 - variant % 2)]):
        for k in range(2):
            c.ascii(ox + dx + k * 8 - (4 if row == 1 and k == 1 and dx > 4 else 0), oy + dy, clump)


def path(c: Canvas, ox: int, oy: int, mask: int) -> None:
    c.rect(ox, oy, T, T, 3)
    rng = random.Random(7 + mask)
    for _ in range(5):
        c.set(ox + rng.randrange(2, 14), oy + rng.randrange(2, 14), 2)
    # Grass meets path: a ragged dark seam plus a soft mid-tone line.
    if not mask & UP:
        c.hline(ox, ox + 15, oy, 1)
        for x in range(0, 16, 3):
            c.set(ox + x + 1, oy + 1, 2)
    if not mask & DOWN:
        c.hline(ox, ox + 15, oy + 15, 1)
        for x in range(0, 16, 3):
            c.set(ox + x, oy + 14, 2)
    if not mask & LEFT:
        c.vline(ox, oy, oy + 15, 1)
        for y in range(0, 16, 3):
            c.set(ox + 1, oy + y + 1, 2)
    if not mask & RIGHT:
        c.vline(ox + 15, oy, oy + 15, 1)
        for y in range(0, 16, 3):
            c.set(ox + 14, oy + y, 2)


def water(c: Canvas, ox: int, oy: int, mask: int) -> None:
    c.rect(ox, oy, T, T, 1)
    for (x, y) in [(2, 3), (9, 7), (4, 12)]:
        c.hline(ox + x, ox + x + 3, oy + y, 2)
        c.set(ox + x + 1, oy + y - 1, 3)
        c.set(ox + x + 2, oy + y - 1, 3)
    # Shoreline: a light foam rim and a dark bank on the land side.
    if not mask & UP:
        c.hline(ox, ox + 15, oy, 0)
        c.hline(ox, ox + 15, oy + 1, 3)
        c.checker(ox, oy + 2, T, 1, 2, 1)
    if not mask & DOWN:
        c.hline(ox, ox + 15, oy + 15, 0)
        c.hline(ox, ox + 15, oy + 14, 2)
    if not mask & LEFT:
        c.vline(ox, oy, oy + 15, 0)
        c.vline(ox + 1, oy, oy + 15, 3)
    if not mask & RIGHT:
        c.vline(ox + 15, oy, oy + 15, 0)
        c.vline(ox + 14, oy, oy + 15, 3)


def tree(c: Canvas, ox: int, oy: int, variant: int) -> None:
    grass(c, ox, oy, variant)
    # A round, layered canopy (clumps rather than a cone) with a short trunk.
    rows = ["....000000......",
            "..0022211100....",
            ".022233221110...",
            "0223332221110...",
            "0222322211110...",
            "01222211111100..",
            "0112211111111100",
            "0111111111111110",
            "0111211111121110",
            ".011111111111110",
            "..00111111111100",
            "....0001111000..",
            "......0110......",
            "......0110......",
            ".....001100.....",
            "......0000......"]
    if variant % 2:
        rows = [r[::-1] for r in rows]
    c.ascii(ox, oy, rows)


def wall(c: Canvas, ox: int, oy: int, mask: int) -> None:
    c.rect(ox, oy, T, T, 3)
    # Timber frame: posts at open ends, beam on top, plinth at the bottom.
    c.hline(ox, ox + 15, oy, 1)
    c.hline(ox, ox + 15, oy + 13, 1)
    c.rect(ox, oy + 14, T, 2, 0)
    if not mask & LEFT:
        c.vline(ox, oy, oy + 15, 0)
        c.vline(ox + 1, oy, oy + 13, 1)
    if not mask & RIGHT:
        c.vline(ox + 15, oy, oy + 15, 0)
        c.vline(ox + 14, oy, oy + 13, 1)
    # Round-top window (original shape, not a square grid).
    c.ascii(ox + 4, oy + 3, ["..0000..",
                             ".011110.",
                             "01122110",
                             "01200210",
                             "01122110",
                             "00000000",
                             ".222222."])


def roof(c: Canvas, ox: int, oy: int, mask: int) -> None:
    # Overlapping wooden shingles: rows of 4 px, staggered every other row.
    c.rect(ox, oy, T, T, 1)
    for row in range(4):
        y = oy + row * 4
        c.hline(ox, ox + 15, y, 2)
        c.hline(ox, ox + 15, y + 3, 0)
        for x in range((row % 2) * 4, 16, 8):
            c.vline(ox + x, y + 1, y + 2, 0)
            c.set(ox + x + 1, y + 1, 2)
    if not mask & UP:
        c.hline(ox, ox + 15, oy, 0)
        c.hline(ox, ox + 15, oy + 1, 2)
        c.hline(ox, ox + 15, oy + 2, 3)
    if not mask & DOWN:
        # Eave casting a shadow on the wall below.
        c.hline(ox, ox + 15, oy + 13, 2)
        c.hline(ox, ox + 15, oy + 14, 0)
        c.checker(ox, oy + 15, T, 1, 0, 1)
    if not mask & LEFT:
        c.vline(ox, oy, oy + 15, 0)
        c.vline(ox + 1, oy + 1, oy + 13, 2)
    if not mask & RIGHT:
        c.vline(ox + 15, oy, oy + 15, 0)


def door(c: Canvas, ox: int, oy: int) -> None:
    wall(c, ox, oy, LEFT | RIGHT)
    c.rect(ox + 2, oy + 2, 12, 12, 3)
    c.ascii(ox + 3, oy + 1, ["..000000..",
                             ".01111110.",
                             "0112112110",
                             "0112112110",
                             "0112112110",
                             "0111111110",
                             "0112112130",
                             "0112112110",
                             "0112112110",
                             "0111111110",
                             "0112112110",
                             "0111111110",
                             "0000000000"])
    c.hline(ox + 1, ox + 14, oy + 14, 2)
    c.hline(ox + 1, ox + 14, oy + 15, 1)


def floor(c: Canvas, ox: int, oy: int) -> None:
    c.rect(ox, oy, T, T, 3)
    for y in (3, 7, 11, 15):
        c.hline(ox, ox + 15, oy + y, 2)
    for i, y in enumerate((0, 4, 8, 12)):
        x = (5 + i * 6) % 16
        c.vline(ox + x, oy + y, oy + y + 2, 2)


def fence(c: Canvas, ox: int, oy: int, mask: int) -> None:
    grass(c, ox, oy, 1)
    # Split-rail fence: two rails, one post per tile.
    for y in (5, 10):
        c.hline(ox, ox + 15, oy + y, 0)
        c.hline(ox, ox + 15, oy + y + 1, 3)
        c.hline(ox, ox + 15, oy + y + 2, 0)
    c.ascii(ox + 6, oy + 2, ["0000",
                             "0330",
                             "0320",
                             "0320",
                             "0320",
                             "0320",
                             "0320",
                             "0320",
                             "0320",
                             "0320",
                             "0320",
                             "0220",
                             "0000"])
    if not mask & LEFT:
        c.rect(ox, oy + 5, 3, 8, None)
        grass_patch = Canvas(3, 8)
        c.rect(ox, oy + 5, 3, 8, 2)
    if not mask & RIGHT:
        c.rect(ox + 13, oy + 5, 3, 8, 2)


def sign(c: Canvas, ox: int, oy: int) -> None:
    grass(c, ox, oy, 2)
    # Hanging board on a crossbar post (not a plain rectangle on a stick).
    c.ascii(ox + 1, oy + 1, ["00000000000000",
                             "0..0......0..0",
                             ".0000000000000",
                             ".0333333333330",
                             ".0311111111230",
                             ".0333333333330",
                             ".0311111123330",
                             ".0333333333330",
                             ".0222222222220",
                             ".0000000000000",
                             "......00......",
                             "......00......",
                             "......00......",
                             ".....0110.....",
                             "......00......"])


def flower(c: Canvas, ox: int, oy: int, variant: int) -> None:
    grass(c, ox, oy, variant + 2)
    rng = random.Random(40 + variant)
    spots = [(2, 2), (9, 4), (4, 9), (11, 11)]
    for (x, y) in spots[: 3 if variant % 2 else 4]:
        x += rng.randrange(0, 2)
        c.ascii(ox + x, oy + y, [".3.", "303", ".3.", ".1."])


def counter(c: Canvas, ox: int, oy: int) -> None:
    floor(c, ox, oy)
    c.rect(ox, oy + 2, T, 12, 1)
    c.hline(ox, ox + 15, oy + 2, 0)
    c.hline(ox, ox + 15, oy + 3, 3)
    c.hline(ox, ox + 15, oy + 4, 2)
    for x in (3, 11):
        c.vline(ox + x, oy + 6, oy + 12, 0)
    c.hline(ox, ox + 15, oy + 13, 0)


def inner_wall(c: Canvas, ox: int, oy: int) -> None:
    c.rect(ox, oy, T, T, 2)
    for x in range(0, 16, 4):
        c.vline(ox + x, oy, oy + 9, 1)
    c.hline(ox, ox + 15, oy + 10, 0)
    c.rect(ox, oy + 11, T, 4, 1)
    c.hline(ox, ox + 15, oy + 15, 0)


def spring(c: Canvas, ox: int, oy: int) -> None:
    floor(c, ox, oy)
    c.ascii(ox, oy, ["....00000000....",
                     "..002222222200..",
                     ".02211111111220.",
                     ".02111131111120.",
                     "0211113331111120",
                     "0211111311111120",
                     "0211111111111120",
                     "0211311111131120",
                     "0211111111111120",
                     "0211111111111120",
                     "0211111131111120",
                     ".02111111111120.",
                     ".02211111111220.",
                     "..002222222200..",
                     "....00000000....",
                     "................"])


def rift(c: Canvas, ox: int, oy: int) -> None:
    grass(c, ox, oy, 3)
    # A jagged tear in the ground with a bright seam.
    c.ascii(ox, oy, ["......0.........",
                     ".....010........",
                     ".....0310.......",
                     "....03310.......",
                     "...0133310......",
                     "...033330.......",
                     "..01333310......",
                     "...0333331 0....".replace(" ", "0"),
                     "....0133330.....",
                     "...013333310....",
                     "....03333310....",
                     ".....0133310....",
                     "......033310....",
                     ".......03310....",
                     "........0310....",
                     ".........00....."])


def cliff(c: Canvas, ox: int, oy: int, mask: int) -> None:
    # Rock face made of stacked, rounded stones (dark gaps between them); grassy lip on top,
    # cast shadow at the foot. Deliberately irregular so it never reads as a brick wall.
    c.rect(ox, oy, T, T, 0)
    stones = [(0, 0, 7, 6), (7, 0, 9, 5), (0, 6, 5, 5), (5, 5, 6, 6), (11, 5, 5, 6),
              (0, 11, 8, 5), (8, 11, 8, 5)]
    for (x, y, w, h) in stones:
        c.rect(ox + x + 1, oy + y + 1, w - 1, h - 1, 1)
        c.hline(ox + x + 2, ox + x + w - 2, oy + y + 1, 2)
        c.vline(ox + x + 1, oy + y + 2, oy + y + h - 2, 2)
        c.set(ox + x + 2, oy + y + 2, 3)
    if not mask & UP:
        c.rect(ox, oy, T, 3, 2)
        for x in range(0, 16, 3):
            c.set(ox + x, oy + 1, 1)
            c.set(ox + x + 1, oy + 2, 1)
        c.hline(ox, ox + 15, oy + 3, 0)
    if not mask & DOWN:
        c.hline(ox, ox + 15, oy + 14, 0)
        c.checker(ox, oy + 15, T, 1, 1, 2)
    if not mask & LEFT:
        c.vline(ox, oy, oy + 15, 0)
    if not mask & RIGHT:
        c.vline(ox + 15, oy, oy + 15, 0)


def stairs(c: Canvas, ox: int, oy: int) -> None:
    c.rect(ox, oy, T, T, 2)
    for y in range(0, T, 4):
        c.hline(ox + 1, ox + 14, oy + y, 3)
        c.hline(ox + 1, ox + 14, oy + y + 3, 0)
    c.vline(ox, oy, oy + 15, 0)
    c.vline(ox + 15, oy, oy + 15, 0)


def reeds(c: Canvas, ox: int, oy: int, variant: int) -> None:
    water(c, ox, oy, 15)
    stalk = ["0.", "0.", "3.", "3.", "2.", "2.", "2.", "2."]
    rng = random.Random(60 + variant)
    for i, x in enumerate([1, 4, 7, 10, 13]):
        y = rng.randrange(1, 7)
        c.ascii(ox + x, oy + y, stalk[: 16 - y])
        c.vline(ox + x, oy + y + 8, oy + 15, 2)
        if i % 2 == 0:
            c.set(ox + x + 1, oy + y + 4, 3)


def scree(c: Canvas, ox: int, oy: int, variant: int) -> None:
    c.rect(ox, oy, T, T, 2)
    rng = random.Random(80 + variant)
    for _ in range(9):
        x, y = rng.randrange(0, 14), rng.randrange(0, 14)
        c.ascii(ox + x, oy + y, ["33", "10"] if rng.random() < 0.6 else ["3", "0"])
    for _ in range(4):
        c.set(ox + rng.randrange(0, 16), oy + rng.randrange(0, 16), 1)


def pier(c: Canvas, ox: int, oy: int, mask: int) -> None:
    water(c, ox, oy, 15)
    x0 = 0 if mask & LEFT else 2
    x1 = 15 if mask & RIGHT else 13
    c.rect(ox + x0, oy, x1 - x0 + 1, T, 3)
    for x in range(x0 + 4, x1, 4):
        c.vline(ox + x, oy, oy + 15, 2)
    for y in (2, 9):
        c.set(ox + x0 + 2, oy + y, 1)
        c.set(ox + x1 - 2, oy + y, 1)
    if not mask & LEFT:
        c.vline(ox + x0, oy, oy + 15, 0)
        c.rect(ox + x0 - 1, oy + 6, 1, 3, 0)
    if not mask & RIGHT:
        c.vline(ox + x1, oy, oy + 15, 0)
        c.rect(ox + x1 + 1, oy + 6, 1, 3, 0)
    if not mask & DOWN:
        c.hline(ox + x0, ox + x1, oy + 15, 0)
    if not mask & UP:
        c.hline(ox + x0, ox + x1, oy, 0)


def tower(c: Canvas, ox: int, oy: int) -> None:
    grass(c, ox, oy, 0)
    c.rect(ox + 2, oy, 12, T, 3)
    for y in range(0, T):
        for x in range(2, 14):
            if (y - x // 3) % 8 < 3:
                c.set(ox + x, oy + y, 1)
    c.vline(ox + 2, oy, oy + 15, 0)
    c.vline(ox + 13, oy, oy + 15, 0)
    c.vline(ox + 3, oy, oy + 15, 2)


def lamp(c: Canvas, ox: int, oy: int) -> None:
    grass(c, ox, oy, 1)
    c.ascii(ox, oy, ["......0000......",
                     ".....011110.....",
                     "....01111110....",
                     "..000000000000..",
                     "...0333333330...",
                     "...0303333030...",
                     "...0333223330...",
                     "...0332112330...",
                     "...0332112330...",
                     "...0333223330...",
                     "...0303333030...",
                     "..000000000000..",
                     "..022222222220..",
                     "...0333113330...",
                     "...0331113330...",
                     "...0333113330..."])


def rock(c: Canvas, ox: int, oy: int, variant: int) -> None:
    grass(c, ox, oy, variant)
    c.ascii(ox, oy + 2, ["....000000......",
                         "..0033332200....",
                         ".033332222210...",
                         ".0333222222100..",
                         "03322222222110..",
                         "03222222221110..",
                         "02222222211110..",
                         "02222221111110..",
                         ".0111111111100..",
                         "..00011110000...",
                         "....0000........",
                         "..1111111111....",
                         "................"])


# --- Area 3 (world) placeholders: simple shapes in the Era I inks; area 6 owns the final look.

def wade(c: Canvas, ox: int, oy: int, mask: int) -> None:
    # Shallow water: lighter than the lake, with stepping stones showing through.
    water(c, ox, oy, mask)
    c.checker(ox + 2, oy + 2, 12, 12, 2, 1)
    for (x, y) in [(3, 5), (10, 10)]:
        c.ascii(ox + x, oy + y, [".00.", "0330", "0220", ".00."])


def boulder(c: Canvas, ox: int, oy: int) -> None:
    floor_like = 2
    c.rect(ox, oy, T, T, floor_like)
    c.ascii(ox, oy + 1, ["....00000000....",
                         "...0333322220...",
                         "..033332222210..",
                         ".03332222222110.",
                         ".03322222221110.",
                         ".03222222211110.",
                         ".02222222111110.",
                         ".02222221111110.",
                         ".02222111111110.",
                         ".01111111111110.",
                         "..011111111110..",
                         "...0000000000...",
                         "....11111111....",
                         "................"])


def plate(c: Canvas, ox: int, oy: int) -> None:
    c.rect(ox, oy, T, T, 2)
    c.rect(ox + 2, oy + 2, 12, 12, 0)
    c.rect(ox + 3, oy + 3, 10, 10, 1)
    c.rect(ox + 5, oy + 5, 6, 6, 3)
    c.rect(ox + 6, oy + 6, 4, 4, 2)


def cracked(c: Canvas, ox: int, oy: int) -> None:
    c.rect(ox, oy, T, T, 2)
    for (x, y) in [(2, 3), (3, 4), (4, 4), (5, 5), (6, 6), (6, 7), (7, 8), (8, 8), (9, 9),
                   (10, 10), (11, 10), (12, 11), (6, 8), (5, 9), (4, 10), (9, 7), (10, 6), (11, 5)]:
        c.set(ox + x, oy + y, 0)
    for (x, y) in [(3, 3), (5, 4), (7, 7), (9, 8), (11, 9)]:
        c.set(ox + x, oy + y, 3)


def vines(c: Canvas, ox: int, oy: int, mask: int) -> None:
    cliff(c, ox, oy, mask)
    for x in (2, 7, 12):
        for y in range(0, 16):
            if (y + x) % 5 != 4:
                c.set(ox + x + (y // 4) % 2, oy + y, 2)
        for y in (3, 9, 14):
            c.ascii(ox + x - 1, oy + y, ["232"])


def plank_gap(c: Canvas, ox: int, oy: int) -> None:
    # A gap in the ground with a chalk mark where a plank fits.
    c.rect(ox, oy, T, T, 0)
    c.hline(ox, ox + 15, oy, 2)
    c.hline(ox, ox + 15, oy + 1, 1)
    c.hline(ox, ox + 15, oy + 15, 2)
    for x in range(2, 14, 3):
        c.set(ox + x, oy + 8, 3)


VARIANT_ROWS = 16


def build_tiles(path_out: str) -> None:
    c = Canvas(T * len(KINDS), T * VARIANT_ROWS)
    for v in range(VARIANT_ROWS):
        oy = v * T
        for k, name in enumerate(KINDS):
            ox = k * T
            if name == "GRASS":
                grass(c, ox, oy, v % 4)
            elif name == "TALL_GRASS":
                tall_grass(c, ox, oy, v % 4)
            elif name == "PATH":
                path(c, ox, oy, v)
            elif name == "WATER":
                water(c, ox, oy, v)
            elif name == "TREE":
                tree(c, ox, oy, v % 4)
            elif name == "WALL":
                wall(c, ox, oy, v)
            elif name == "ROOF":
                roof(c, ox, oy, v)
            elif name == "DOOR":
                door(c, ox, oy)
            elif name == "FLOOR":
                floor(c, ox, oy)
            elif name == "FENCE":
                fence(c, ox, oy, v)
            elif name == "SIGN":
                sign(c, ox, oy)
            elif name == "FLOWER":
                flower(c, ox, oy, v % 4)
            elif name == "COUNTER":
                counter(c, ox, oy)
            elif name == "INNER_WALL":
                inner_wall(c, ox, oy)
            elif name == "SPRING":
                spring(c, ox, oy)
            elif name == "RIFT":
                rift(c, ox, oy)
            elif name == "CLIFF":
                cliff(c, ox, oy, v)
            elif name == "STAIRS":
                stairs(c, ox, oy)
            elif name == "REEDS":
                reeds(c, ox, oy, v % 4)
            elif name == "SCREE":
                scree(c, ox, oy, v % 4)
            elif name == "PIER":
                pier(c, ox, oy, v)
            elif name == "TOWER":
                tower(c, ox, oy)
            elif name == "LAMP":
                lamp(c, ox, oy)
            elif name == "ROCK":
                rock(c, ox, oy, v % 4)
            elif name == "WADE":
                wade(c, ox, oy, v)
            elif name == "BOULDER":
                boulder(c, ox, oy)
            elif name == "PLATE":
                plate(c, ox, oy)
            elif name == "CRACKED":
                cracked(c, ox, oy)
            elif name == "VINES":
                vines(c, ox, oy, 15)
            elif name == "PLANK":
                plank_gap(c, ox, oy)
    c.save(path_out)


