def build_char(style: str, path_out: str) -> None:
    head_key, body_key = STYLES[style]
    sheet = Canvas(T * 4, T * 2)
    for col, d in enumerate(["down", "up", "left", "right"]):
        src = "right" if d == "left" else d
        for frame in range(2):
            f = Canvas(T, T)
            f.ascii(0, 0, HEADS[head_key][src])
            f.ascii(0, 8, BODIES[body_key][src])
            legs = (ROBE_HEM if body_key == "robe" else LEGS)[src][frame]
            f.ascii(0, 13, legs)
            if d == "left":
                f = f.mirrored()
            sheet.blit(f, col * T, frame * T)
    sheet.save(path_out)


def main() -> None:
    root = os.path.join(os.path.dirname(__file__), "..", "..", "art", "era1")
    os.makedirs(os.path.join(root, "tiles"), exist_ok=True)
    os.makedirs(os.path.join(root, "chars"), exist_ok=True)
    build_tiles(os.path.join(root, "tiles", "overworld.png"))
    for style in STYLES:
        build_char(style, os.path.join(root, "chars", f"{style}.png"))


if __name__ == "__main__":
    main()
